#!/usr/bin/env python3
import base64
import getpass
import hashlib
import hmac
import os
import sys
import termios
import textwrap
from dataclasses import dataclass

VERSION = "v0.0.0-20260414014000-96fce988442d"
REPORT = "age: report unexpected or unhelpful errors at https://filippo.io/age/report"
USAGE = """Usage:
    age [--encrypt] (-r RECIPIENT | -R PATH)... [--armor] [-o OUTPUT] [INPUT]
    age [--encrypt] --passphrase [--armor] [-o OUTPUT] [INPUT]
    age --decrypt [-i PATH]... [-o OUTPUT] [INPUT]

Options:
    -e, --encrypt               Encrypt the input to the output. Default if omitted.
    -d, --decrypt               Decrypt the input to the output.
    -o, --output OUTPUT         Write the result to the file at path OUTPUT.
    -a, --armor                 Encrypt to a PEM encoded format.
    -p, --passphrase            Encrypt with a passphrase.
    -r, --recipient RECIPIENT   Encrypt to the specified RECIPIENT. Can be repeated.
    -R, --recipients-file PATH  Encrypt to recipients listed at PATH. Can be repeated.
    -i, --identity PATH         Use the identity file at PATH. Can be repeated.

INPUT defaults to standard input, and OUTPUT defaults to standard output.
If OUTPUT exists, it will be overwritten.

RECIPIENT can be an age public key generated by age-keygen ("age1...")
or an SSH public key ("ssh-ed25519 AAAA...", "ssh-rsa AAAA...").

Recipient files contain one or more recipients, one per line. Empty lines
and lines starting with "#" are ignored as comments. "-" may be used to
read recipients from standard input.

Identity files contain one or more secret keys ("AGE-SECRET-KEY-1..."),
one per line, or an SSH key. Empty lines and lines starting with "#" are
ignored as comments. Passphrase encrypted age files can be used as
identity files. Multiple key files can be provided, and any unused ones
will be ignored. "-" may be used to read identities from standard input.

When --encrypt is specified explicitly, -i can also be used to encrypt to an
identity file symmetrically, instead or in addition to normal recipients.

Example:
    $ age-keygen -o key.txt
    Public key: age1ql3z7hjy54pw3hyww5ayyfg7zqgvc7w3j2elw8zmrj2kg5sfn9aqmcac8p
    $ tar cvz ~/data | age -r age1ql3z7hjy54pw3hyww5ayyfg7zqgvc7w3j2kg5sfn9aqmcac8p > data.tar.gz.age
    $ age --decrypt -i key.txt -o data.tar.gz data.tar.gz.age
"""

# ---------------------------------------------------------------------------
# CLI helpers

class AgeError(Exception):
    def __init__(self, msg, hints=None):
        super().__init__(msg)
        self.msg = msg
        self.hints = hints or []

class HeaderError(Exception):
    pass

class DecryptError(Exception):
    pass


def fatal(msg, hints=None, code=1):
    sys.stderr.write(f"age: error: {msg}\n")
    for h in (hints or []):
        sys.stderr.write(f"age: hint: {h}\n")
    sys.stderr.write(REPORT + "\n")
    raise SystemExit(code)


def flag_error(msg):
    sys.stderr.write(msg + "\n")
    sys.stderr.write(USAGE)
    raise SystemExit(2)


def parse_bool(s, name):
    true = {"1", "t", "T", "TRUE", "true", "True"}
    false = {"0", "f", "F", "FALSE", "false", "False"}
    if s in true:
        return True
    if s in false:
        return False
    flag_error(f'invalid boolean value "{s}" for -{name}: parse error')


@dataclass
class Options:
    encrypt: bool = False
    decrypt: bool = False
    encrypt_seen: bool = False
    decrypt_seen: bool = False
    output: str = None
    armor: bool = False
    passphrase: bool = False
    recipients: list = None
    recipient_files: list = None
    identities: list = None
    plugins: list = None
    inputs: list = None
    stopped_by_double_dash: bool = False

    def __post_init__(self):
        self.recipients = []
        self.recipient_files = []
        self.identities = []
        self.plugins = []
        self.inputs = []


def parse_args(argv):
    o = Options()
    i = 0
    string_flags = {
        "-o": ("o", "output"), "--output": ("output", "output"),
        "-r": ("r", "recipient"), "--recipient": ("recipient", "recipient"),
        "-R": ("R", "recipients-file"), "--recipients-file": ("recipients-file", "recipients-file"),
        "-i": ("i", "identity"), "--identity": ("identity", "identity"),
        "-j": ("j", "plugin"),
    }
    bool_flags = {
        "-e": ("e", "encrypt"), "--encrypt": ("encrypt", "encrypt"),
        "-d": ("d", "decrypt"), "--decrypt": ("decrypt", "decrypt"),
        "-a": ("a", "armor"), "--armor": ("armor", "armor"),
        "-p": ("p", "passphrase"), "--passphrase": ("passphrase", "passphrase"),
        "-h": ("h", "help"), "--help": ("help", "help"),
    }
    while i < len(argv):
        a = argv[i]
        if a == "--":
            o.stopped_by_double_dash = True
            o.inputs.extend(argv[i+1:])
            break
        if a == "-" or not a.startswith("-"):
            o.inputs.extend(argv[i:])
            break

        # Long flag with =.
        name = a
        val = None
        if a.startswith("--") and "=" in a:
            name, val = a.split("=", 1)
        elif a.startswith("-") and not a.startswith("--") and "=" in a:
            name, val = a.split("=", 1)

        if name == "--version":
            if val is not None:
                flag_error(f'flag provided but not defined: -version')
            print(VERSION)
            raise SystemExit(0)

        if name in bool_flags:
            shortname, attr = bool_flags[name]
            if attr == "help":
                if val is not None:
                    flag_error(f'invalid boolean value "{val}" for -{shortname}: parse error')
                sys.stderr.write(USAGE)
                raise SystemExit(0)
            b = True if val is None else parse_bool(val, shortname)
            if attr == "encrypt":
                o.encrypt = b; o.encrypt_seen = True
            elif attr == "decrypt":
                o.decrypt = b; o.decrypt_seen = True
            elif attr == "armor":
                o.armor = b
            elif attr == "passphrase":
                o.passphrase = b
            i += 1
            continue

        if name in string_flags:
            shortname, attr = string_flags[name]
            if val is None:
                if i + 1 >= len(argv):
                    flag_error(f"flag needs an argument: -{shortname}")
                val = argv[i+1]
                i += 2
            else:
                i += 1
            if attr == "output":
                o.output = val
            elif attr == "recipient":
                o.recipients.append(val)
            elif attr == "recipients-file":
                o.recipient_files.append(val)
            elif attr == "identity":
                o.identities.append(val)
            elif attr == "plugin":
                o.plugins.append(val)
            continue

        # Unknown flags. Go's flag package reports --foo as -foo.
        if a.startswith("--"):
            unk = "-" + a[2:].split("=", 1)[0]
        else:
            unk = a.split("=", 1)[0]
        flag_error(f"flag provided but not defined: {unk}")
    return o


def quote_args(args):
    return " ".join('"' + x.replace('"', '\\"') + '"' for x in args)


def validate_options(o, argv):
    if len(o.inputs) > 1:
        hints = []
        if (not o.stopped_by_double_dash) and any(x.startswith("-") for x in o.inputs[1:]):
            hints.append("the input file must be specified after all flags")
            # Best-effort suggestion matching the common case.
            flags = [x for x in o.inputs[1:]]
            hints.append("did you mean:")
            hints.append("    " + sys.argv[0] + " " + " ".join(flags) + " " + o.inputs[0])
        else:
            hints.append("only a single input file may be specified at a time")
        fatal("too many INPUT arguments: " + quote_args(o.inputs), hints)

    if o.encrypt and o.decrypt:
        fatal("-e/--encrypt can't be used with -d/--decrypt")

    decrypt_mode = o.decrypt
    encrypt_mode = not decrypt_mode

    if decrypt_mode:
        if o.passphrase:
            fatal("-p/--passphrase can't be used with -d/--decrypt",
                  ["note that password protected files are detected automatically"])
        if o.recipients:
            fatal("-r/--recipient can't be used with -d/--decrypt",
                  ["did you mean to use -i/--identity to specify a private key?"])
        if o.recipient_files:
            fatal("-R/--recipients-file can't be used with -d/--decrypt",
                  ["did you mean to use -i/--identity to specify a private key?"])
        if o.armor:
            fatal("-a/--armor can't be used with -d/--decrypt",
                  ["note that armored files are detected automatically, try again without -a/--armor"])
    else:
        if (o.identities or o.plugins) and not (o.encrypt_seen and o.encrypt):
            fatal("-i/--identity and -j can't be used in encryption mode unless symmetric encryption is explicitly selected with -e/--encrypt",
                  ["did you forget to specify -d/--decrypt?"])
        if o.passphrase:
            if o.recipients:
                fatal("-p/--passphrase can't be combined with -r/--recipient")
            if o.recipient_files:
                fatal("-p/--passphrase can't be combined with -R/--recipients-file")
            if o.identities or o.plugins:
                fatal("-p/--passphrase can't be combined with -i/--identity and -j")
        else:
            if not (o.recipients or o.recipient_files or o.identities or o.plugins):
                fatal("missing recipients", ["did you forget to specify -r/--recipient, -R/--recipients-file or -p/--passphrase?"])
    return decrypt_mode


# ---------------------------------------------------------------------------
# Encoding primitives

CHARSET = "qpzry9x8gf2tvdw0s3jn54khce6mua7l"
CHARMAP = {c: i for i, c in enumerate(CHARSET)}


def bech32_polymod(values):
    chk = 1
    for v in values:
        top = chk >> 25
        chk = ((chk & 0x1ffffff) << 5) ^ v
        for i, g in enumerate([0x3b6a57b2, 0x26508e6d, 0x1ea119fa, 0x3d4233dd, 0x2a1462b3]):
            if (top >> i) & 1:
                chk ^= g
    return chk


def bech32_hrp_expand(hrp):
    return [ord(x) >> 5 for x in hrp] + [0] + [ord(x) & 31 for x in hrp]


def convert_bits(data, frombits, tobits, pad=True):
    acc = 0
    bits = 0
    ret = []
    maxv = (1 << tobits) - 1
    max_acc = (1 << (frombits + tobits - 1)) - 1
    for value in data:
        if value < 0 or (value >> frombits):
            raise ValueError("invalid data range")
        acc = ((acc << frombits) | value) & max_acc
        bits += frombits
        while bits >= tobits:
            bits -= tobits
            ret.append((acc >> bits) & maxv)
    if pad:
        if bits:
            ret.append((acc << (tobits - bits)) & maxv)
    elif bits >= frombits or ((acc << (tobits - bits)) & maxv):
        raise ValueError("invalid padding")
    return ret


def bech32_decode(s):
    if any(ord(x) < 33 or ord(x) > 126 for x in s):
        raise ValueError("invalid character")
    if s.lower() != s and s.upper() != s:
        raise ValueError("mixed case")
    sl = s.lower()
    pos = sl.rfind("1")
    if pos < 1 or pos + 7 > len(sl):
        raise ValueError(f"separator '1' at invalid position: pos={pos}, len={len(sl)}")
    if any(c not in CHARMAP for c in sl[pos+1:]):
        raise ValueError("invalid character")
    hrp = sl[:pos]
    data = [CHARMAP[c] for c in sl[pos+1:]]
    if bech32_polymod(bech32_hrp_expand(hrp) + data) != 1:
        raise ValueError("invalid checksum")
    decoded = bytes(convert_bits(data[:-6], 5, 8, False))
    return hrp, decoded


def bech32_encode(hrp, data_bytes):
    data = convert_bits(data_bytes, 8, 5, True)
    pm = bech32_polymod(bech32_hrp_expand(hrp) + data + [0, 0, 0, 0, 0, 0]) ^ 1
    combined = data + [(pm >> 5 * (5 - i)) & 31 for i in range(6)]
    return hrp + "1" + "".join(CHARSET[d] for d in combined)


def b64e(b):
    return base64.b64encode(b).rstrip(b"=").decode("ascii")


def b64d(s):
    if isinstance(s, bytes):
        ss = s.strip()
    else:
        ss = s.strip().encode("ascii")
    return base64.b64decode(ss + b"=" * ((4 - len(ss) % 4) % 4), validate=True)


# ---------------------------------------------------------------------------
# Crypto primitives: X25519, HKDF, ChaCha20-Poly1305

P = 2 ** 255 - 19
A24 = 121665
BASEPOINT = (9).to_bytes(32, "little")


def x25519(scalar, u):
    k = bytearray(scalar)
    if len(k) != 32 or len(u) != 32:
        raise ValueError("bad X25519 input length")
    k[0] &= 248
    k[31] &= 127
    k[31] |= 64
    kk = int.from_bytes(k, "little")
    x1 = int.from_bytes(u, "little")
    x2, z2 = 1, 0
    x3, z3 = x1, 1
    swap = 0
    for t in range(254, -1, -1):
        kt = (kk >> t) & 1
        swap ^= kt
        if swap:
            x2, x3 = x3, x2
            z2, z3 = z3, z2
        swap = kt
        A = (x2 + z2) % P
        AA = (A * A) % P
        B = (x2 - z2) % P
        BB = (B * B) % P
        E = (AA - BB) % P
        C = (x3 + z3) % P
        D = (x3 - z3) % P
        DA = (D * A) % P
        CB = (C * B) % P
        x3 = ((DA + CB) ** 2) % P
        z3 = (x1 * ((DA - CB) ** 2 % P)) % P
        x2 = (AA * BB) % P
        z2 = (E * (AA + A24 * E)) % P
    if swap:
        x2, x3 = x3, x2
        z2, z3 = z3, z2
    return (x2 * pow(z2, P - 2, P) % P).to_bytes(32, "little")


def hkdf_sha256(ikm, salt, info, length=32):
    if salt is None:
        salt = b"\x00" * hashlib.sha256().digest_size
    prk = hmac.new(salt, ikm, hashlib.sha256).digest()
    out = b""
    t = b""
    counter = 1
    while len(out) < length:
        t = hmac.new(prk, t + info + bytes([counter]), hashlib.sha256).digest()
        out += t
        counter += 1
    return out[:length]


def rotl32(v, n):
    return ((v << n) & 0xffffffff) | (v >> (32 - n))


def quarter_round(s, a, b, c, d):
    s[a] = (s[a] + s[b]) & 0xffffffff; s[d] = rotl32(s[d] ^ s[a], 16)
    s[c] = (s[c] + s[d]) & 0xffffffff; s[b] = rotl32(s[b] ^ s[c], 12)
    s[a] = (s[a] + s[b]) & 0xffffffff; s[d] = rotl32(s[d] ^ s[a], 8)
    s[c] = (s[c] + s[d]) & 0xffffffff; s[b] = rotl32(s[b] ^ s[c], 7)


def chacha20_block(key, counter, nonce):
    constants = b"expand 32-byte k"
    state = [int.from_bytes(constants[i:i+4], "little") for i in range(0, 16, 4)]
    state += [int.from_bytes(key[i:i+4], "little") for i in range(0, 32, 4)]
    state += [counter & 0xffffffff]
    state += [int.from_bytes(nonce[i:i+4], "little") for i in range(0, 12, 4)]
    working = state[:]
    for _ in range(10):
        quarter_round(working, 0, 4, 8, 12)
        quarter_round(working, 1, 5, 9, 13)
        quarter_round(working, 2, 6, 10, 14)
        quarter_round(working, 3, 7, 11, 15)
        quarter_round(working, 0, 5, 10, 15)
        quarter_round(working, 1, 6, 11, 12)
        quarter_round(working, 2, 7, 8, 13)
        quarter_round(working, 3, 4, 9, 14)
    return b"".join(((working[i] + state[i]) & 0xffffffff).to_bytes(4, "little") for i in range(16))


def chacha20_xor(key, counter, nonce, data):
    out = bytearray(len(data))
    pos = 0
    ctr = counter
    while pos < len(data):
        block = chacha20_block(key, ctr, nonce)
        ctr = (ctr + 1) & 0xffffffff
        chunk = data[pos:pos+64]
        for i, b in enumerate(chunk):
            out[pos+i] = b ^ block[i]
        pos += len(chunk)
    return bytes(out)


def poly1305_mac(msg, key):
    r = int.from_bytes(key[:16], "little")
    s = int.from_bytes(key[16:], "little")
    r &= 0x0ffffffc0ffffffc0ffffffc0fffffff
    p = (1 << 130) - 5
    acc = 0
    for i in range(0, len(msg), 16):
        n = int.from_bytes(msg[i:i+16] + b"\x01", "little")
        acc = ((acc + n) * r) % p
    return ((acc + s) % (1 << 128)).to_bytes(16, "little")


def pad16(x):
    return b"" if len(x) % 16 == 0 else b"\x00" * (16 - len(x) % 16)


def aead_encrypt(key, nonce, plaintext, aad=b""):
    ciphertext = chacha20_xor(key, 1, nonce, plaintext)
    otk = chacha20_block(key, 0, nonce)[:32]
    mac_data = aad + pad16(aad) + ciphertext + pad16(ciphertext) + len(aad).to_bytes(8, "little") + len(ciphertext).to_bytes(8, "little")
    tag = poly1305_mac(mac_data, otk)
    return ciphertext + tag


def aead_decrypt(key, nonce, ciphertext, aad=b""):
    if len(ciphertext) < 16:
        return None
    c = ciphertext[:-16]
    tag = ciphertext[-16:]
    otk = chacha20_block(key, 0, nonce)[:32]
    mac_data = aad + pad16(aad) + c + pad16(c) + len(aad).to_bytes(8, "little") + len(c).to_bytes(8, "little")
    expected = poly1305_mac(mac_data, otk)
    if not hmac.compare_digest(expected, tag):
        return None
    return chacha20_xor(key, 1, nonce, c)


# ---------------------------------------------------------------------------
# age file implementation (classic native X25519 and passphrase stanzas)

CHUNK_SIZE = 64 * 1024

@dataclass
class Identity:
    secret: bytes
    public: bytes

@dataclass
class Stanza:
    typ: str
    args: list
    body: bytes


def parse_classic_recipient(s):
    if not s.startswith("age1"):
        if s.startswith("age1tag1") or s.startswith("age1tagpq1"):
            raise AgeError(f'malformed recipient "{s}": invalid recipient encoding: unsupported recipient type')
        raise AgeError(f'unknown recipient type: "{s}"')
    try:
        hrp, data = bech32_decode(s)
    except ValueError as e:
        raise AgeError(f'malformed recipient "{s}": {e}')
    if hrp != "age" or len(data) != 32:
        raise AgeError(f'malformed recipient "{s}": invalid recipient encoding')
    return data


def parse_identity_line(line):
    if not line.startswith("AGE-SECRET-KEY-1"):
        raise AgeError("unknown identity type")
    try:
        hrp, data = bech32_decode(line.lower())
    except ValueError as e:
        raise AgeError(f"malformed secret key: {e}")
    if hrp != "age-secret-key-" or len(data) != 32:
        raise AgeError("malformed secret key: invalid length")
    return Identity(secret=data, public=x25519(data, BASEPOINT))


def read_text_file(path, what):
    if path == "-":
        return sys.stdin.buffer.read()
    try:
        with open(path, "rb") as f:
            return f.read()
    except OSError as e:
        if what == "identity":
            raise AgeError(f'reading "{path}": failed to open file: open {path}: {e.strerror.lower() if e.strerror else str(e)}')
        raise AgeError(f'open {path}: {e.strerror.lower() if e.strerror else str(e)}')


def load_recipient_file(path, stdin_conflict):
    if path == "-" and stdin_conflict:
        raise AgeError('failed to parse recipient file "-": standard input is used for multiple purposes')
    try:
        data = read_text_file(path, "recipient").decode("utf-8")
    except UnicodeDecodeError:
        raise AgeError(f'failed to parse recipient file "{path}": "{path}": malformed recipient at line 1')
    except AgeError as e:
        if str(e).startswith("open "):
            raise AgeError(f'failed to open recipients file "{path}": {e.msg}')
        raise
    recips = []
    for lineno, line in enumerate(data.splitlines(), 1):
        if line == "" or line.startswith("#"):
            continue
        if line.startswith("ssh-"):
            # Recognize the documented SSH forms, but this reimplementation does not
            # implement their cryptographic wrapping.
            raise AgeError(f'failed to parse recipient file "{path}": "{path}": malformed recipient at line {lineno}')
        try:
            recips.append(parse_classic_recipient(line))
        except AgeError:
            raise AgeError(f'failed to parse recipient file "{path}": "{path}": malformed recipient at line {lineno}')
    if not recips:
        raise AgeError(f'failed to parse recipient file "{path}": "{path}": no recipients found')
    return recips


def load_identities(path, stdin_conflict, prompt_context=None):
    if path == "-" and stdin_conflict:
        raise AgeError('reading "-": standard input is used for multiple purposes')
    try:
        data = read_text_file(path, "identity")
    except AgeError as e:
        # Match the most common open-file wording.
        if e.msg.startswith(f'reading "{path}"'):
            raise
        raise AgeError(f'reading "{path}": failed to read "{path}": {e.msg}')

    # Passphrase-encrypted identity files are themselves age files.
    if data.startswith(b"age-encryption.org/v1\n") or data.startswith(b"-----BEGIN AGE ENCRYPTED FILE-----"):
        try:
            data = decrypt_age_data(data, [], passphrase_prompt=f'Enter passphrase for identity file "{path}":', identity_file=True)
        except AgeError as e:
            raise AgeError(f'reading "{path}": {e.msg}')

    try:
        text = data.decode("utf-8")
    except UnicodeDecodeError:
        raise AgeError(f'reading "{path}": failed to read "{path}": error at line 1: unknown identity type')
    ids = []
    for lineno, line in enumerate(text.splitlines(), 1):
        if line == "" or line.startswith("#"):
            continue
        try:
            ids.append(parse_identity_line(line))
        except AgeError as e:
            raise AgeError(f'reading "{path}": failed to read "{path}": error at line {lineno}: {e.msg}')
    if not ids:
        raise AgeError(f'reading "{path}": failed to read "{path}": no identities found')
    return ids


def wrap_x25519(file_key, recipient_pub):
    eph_secret = os.urandom(32)
    eph_pub = x25519(eph_secret, BASEPOINT)
    shared = x25519(eph_secret, recipient_pub)
    wrap_key = hkdf_sha256(shared, eph_pub + recipient_pub, b"age-encryption.org/v1/X25519")
    body = aead_encrypt(wrap_key, b"\x00" * 12, file_key)
    return f"-> X25519 {b64e(eph_pub)}\n{b64e(body)}\n".encode("ascii")


def unwrap_x25519(stanza, identity):
    if stanza.typ != "X25519" or len(stanza.args) != 1:
        return None
    try:
        eph_pub = b64d(stanza.args[0])
    except Exception:
        return None
    if len(eph_pub) != 32:
        return None
    shared = x25519(identity.secret, eph_pub)
    wrap_key = hkdf_sha256(shared, eph_pub + identity.public, b"age-encryption.org/v1/X25519")
    fk = aead_decrypt(wrap_key, b"\x00" * 12, stanza.body)
    if fk is not None and len(fk) == 16:
        return fk
    return None


def wrap_scrypt(file_key, passphrase, work_factor=18):
    salt = os.urandom(16)
    key = hashlib.scrypt(passphrase.encode("utf-8"), salt=b"age-encryption.org/v1/scrypt" + salt,
                         n=1 << work_factor, r=8, p=1, dklen=32, maxmem=1024*1024*1024)
    body = aead_encrypt(key, b"\x00" * 12, file_key)
    return f"-> scrypt {b64e(salt)} {work_factor}\n{b64e(body)}\n".encode("ascii")


def unwrap_scrypt(stanza, passphrase):
    if stanza.typ != "scrypt" or len(stanza.args) != 2:
        return None
    try:
        salt = b64d(stanza.args[0])
        logn = int(stanza.args[1])
    except Exception:
        return None
    if logn < 1 or logn > 30:
        return None
    try:
        key = hashlib.scrypt(passphrase.encode("utf-8"), salt=b"age-encryption.org/v1/scrypt" + salt,
                             n=1 << logn, r=8, p=1, dklen=32, maxmem=1024*1024*1024)
    except Exception:
        return None
    fk = aead_decrypt(key, b"\x00" * 12, stanza.body)
    if fk is not None and len(fk) == 16:
        return fk
    return None


def build_age_file(plaintext, recipient_pubs=None, passphrase=None):
    file_key = os.urandom(16)
    pre = b"age-encryption.org/v1\n"
    if passphrase is not None:
        pre += wrap_scrypt(file_key, passphrase)
    else:
        for pub in recipient_pubs:
            pre += wrap_x25519(file_key, pub)
    header_key = hkdf_sha256(file_key, None, b"header")
    mac = hmac.new(header_key, pre + b"---", hashlib.sha256).digest()
    header = pre + b"--- " + b64e(mac).encode("ascii") + b"\n"

    payload_nonce = os.urandom(16)
    payload_key = hkdf_sha256(file_key, payload_nonce, b"payload")
    payload = bytearray(payload_nonce)
    if len(plaintext) == 0:
        nonce = (0).to_bytes(11, "big") + b"\x01"
        payload += aead_encrypt(payload_key, nonce, b"")
    else:
        chunks = (len(plaintext) + CHUNK_SIZE - 1) // CHUNK_SIZE
        for idx in range(chunks):
            chunk = plaintext[idx * CHUNK_SIZE:(idx + 1) * CHUNK_SIZE]
            final = 1 if idx == chunks - 1 else 0
            nonce = idx.to_bytes(11, "big") + bytes([final])
            payload += aead_encrypt(payload_key, nonce, chunk)
    return header + bytes(payload)


def parse_age_header(raw):
    if not raw.startswith(b"age-encryption.org/v1\n"):
        if b"\n" in raw:
            first = raw.split(b"\n", 1)[0] + b"\n"
            raise HeaderError(f'parsing age header: unexpected intro: "{first.decode("latin1")}"')
        raise HeaderError("parsing age header: file is empty")
    pos = len(b"age-encryption.org/v1\n")
    pre = raw[:pos]
    stanzas = []
    cur_type = None
    cur_args = None
    cur_body_lines = []
    while True:
        nl = raw.find(b"\n", pos)
        if nl < 0:
            raise HeaderError("parsing age header: failed to read header: EOF")
        line = raw[pos:nl+1]
        line_no_nl = line[:-1]
        if line.startswith(b"--- "):
            if cur_type is not None:
                try:
                    body = b"".join(b64d(x) for x in cur_body_lines)
                except Exception:
                    raise HeaderError("failed to parse header: malformed body line")
                stanzas.append(Stanza(cur_type, cur_args, body))
            mac_s = line_no_nl[4:]
            try:
                mac = b64d(mac_s)
            except Exception as e:
                raise HeaderError(f'parsing age header: malformed closing line "{line.decode("latin1")}": illegal base64 data at input byte 0')
            payload = raw[nl+1:]
            return stanzas, pre + b"---", mac, payload
        if line.startswith(b"-> "):
            if cur_type is not None:
                try:
                    body = b"".join(b64d(x) for x in cur_body_lines)
                except Exception:
                    raise HeaderError("failed to parse header: malformed body line")
                stanzas.append(Stanza(cur_type, cur_args, body))
            parts = line_no_nl.decode("ascii", "replace").split(" ")
            cur_type = parts[1] if len(parts) > 1 else ""
            cur_args = parts[2:]
            cur_body_lines = []
        else:
            if cur_type is None:
                raise HeaderError(f'parsing age header: malformed line "{line.decode("latin1")}"')
            cur_body_lines.append(line_no_nl)
        pre += line
        pos = nl + 1


def decrypt_payload(file_key, payload):
    if len(payload) < 16 + 16:
        raise DecryptError("failed to decrypt and authenticate payload chunk, file may be corrupted or tampered with")
    payload_nonce = payload[:16]
    ctext = payload[16:]
    payload_key = hkdf_sha256(file_key, payload_nonce, b"payload")
    out = bytearray()
    idx = 0
    pos = 0
    while pos < len(ctext):
        remaining = len(ctext) - pos
        if remaining > CHUNK_SIZE + 16:
            clen = CHUNK_SIZE + 16
            final = 0
        else:
            clen = remaining
            final = 1
        chunk_ct = ctext[pos:pos+clen]
        nonce = idx.to_bytes(11, "big") + bytes([final])
        pt = aead_decrypt(payload_key, nonce, chunk_ct)
        if pt is None:
            raise DecryptError("failed to decrypt and authenticate payload chunk, file may be corrupted or tampered with")
        out += pt
        pos += clen
        idx += 1
    return bytes(out)


def armor_encode(raw):
    b = base64.b64encode(raw).decode("ascii")
    lines = ["-----BEGIN AGE ENCRYPTED FILE-----"]
    lines.extend(textwrap.wrap(b, 64))
    lines.append("-----END AGE ENCRYPTED FILE-----")
    return ("\n".join(lines) + "\n").encode("ascii")


def armor_decode(data):
    text = data.decode("ascii", "strict")
    begin = "-----BEGIN AGE ENCRYPTED FILE-----\n"
    end = "-----END AGE ENCRYPTED FILE-----"
    if not text.startswith(begin):
        return data
    rest = text[len(begin):]
    idx = rest.find(end)
    if idx < 0:
        raise HeaderError("parsing age header: invalid armor")
    b64 = "".join(rest[:idx].splitlines())
    try:
        return base64.b64decode(b64, validate=True)
    except Exception:
        raise HeaderError("parsing age header: invalid armor")


def decrypt_age_data(data, identities, passphrase_prompt="Enter passphrase:", identity_file=False):
    try:
        raw = armor_decode(data) if data.startswith(b"-----BEGIN AGE ENCRYPTED FILE-----") else data
        stanzas, mac_input, mac, payload = parse_age_header(raw)
    except HeaderError as e:
        raise AgeError(f"failed to read header: {e}")

    has_scrypt = any(s.typ == "scrypt" for s in stanzas)
    if has_scrypt and identities:
        raise AgeError("file is passphrase-encrypted but identities were specified with -i/--identity or -j",
                       ["remove all -i/--identity/-j flags to decrypt passphrase-encrypted files"])

    file_key = None
    if has_scrypt:
        try:
            pw = read_passphrase(passphrase_prompt)
        except AgeError as e:
            # Original wraps the read error once more during decryption.
            if str(e.msg).startswith("could not read passphrase"):
                raise AgeError("could not read passphrase: " + e.msg)
            raise
        for s in stanzas:
            fk = unwrap_scrypt(s, pw)
            if fk is not None:
                file_key = fk
                break
        if file_key is None:
            raise AgeError("incorrect passphrase")
    else:
        if not identities:
            raise AgeError("the file is not passphrase-encrypted, identities are required",
                           ["specify identities with -i/--identity or -j to decrypt this file"])
        for ident in identities:
            for s in stanzas:
                fk = unwrap_x25519(s, ident)
                if fk is not None:
                    file_key = fk
                    break
            if file_key is not None:
                break
        if file_key is None:
            raise AgeError("no identity matched any of the recipients")

    header_key = hkdf_sha256(file_key, None, b"header")
    expected_mac = hmac.new(header_key, mac_input, hashlib.sha256).digest()
    if not hmac.compare_digest(expected_mac, mac):
        raise AgeError("bad header MAC")
    try:
        return decrypt_payload(file_key, payload)
    except DecryptError as e:
        raise AgeError(str(e))


# ---------------------------------------------------------------------------
# Passphrase and I/O


def read_passphrase(prompt):
    # Use /dev/tty, matching age's behavior when stdin is data. If unavailable,
    # reproduce the non-interactive error observed from the reference binary.
    try:
        tty = open("/dev/tty", "r+b", buffering=0)
    except OSError:
        raise AgeError("could not read passphrase: standard input is not a terminal, and /dev/tty is not available: open /dev/tty: no such device or address")
    try:
        fd = tty.fileno()
        old = termios.tcgetattr(fd)
        tty.write(prompt.encode("utf-8") + b" ")
        tty.flush()
        try:
            new = old[:]
            new[3] &= ~termios.ECHO
            termios.tcsetattr(fd, termios.TCSADRAIN, new)
            line = tty.readline()
        finally:
            termios.tcsetattr(fd, termios.TCSADRAIN, old)
            tty.write(b"\n")
        if line.endswith(b"\n"):
            line = line[:-1]
        if line.endswith(b"\r"):
            line = line[:-1]
        return line.decode("utf-8", "replace")
    finally:
        tty.close()


def read_new_passphrase():
    pw = read_passphrase("Enter passphrase (leave empty to autogenerate a secure one):")
    if pw == "":
        words = ["release", "response", "step", "brand", "wrap", "ankle", "pair", "unusual", "sword", "train",
                 "hip", "roast", "boring", "snake", "mention", "east", "wasp", "honey", "input", "actress"]
        # Deterministic-looking but random choice; exact word list is not security-critical here.
        pw = "-".join(words[b % len(words)] for b in os.urandom(10))
        sys.stderr.write(f'Using the autogenerated passphrase "{pw}".\n')
        return pw
    while True:
        pw2 = read_passphrase("Confirm passphrase:")
        if pw == pw2:
            return pw
        sys.stderr.write("Passphrases didn't match. Try again.\n")
        pw = read_passphrase("Enter passphrase (leave empty to autogenerate a secure one):")


def open_input(path):
    if path is None or path == "-":
        return sys.stdin.buffer.read()
    try:
        with open(path, "rb") as f:
            return f.read()
    except OSError as e:
        fatal(f'failed to open input file "{path}": open {path}: {e.strerror.lower() if e.strerror else str(e)}')


def write_output(path, data, encrypting=False, armor=False):
    if path is None:
        if encrypting and not armor and sys.stdout.isatty():
            fatal("refusing to output binary to the terminal",
                  ["did you mean to use -a/--armor?", 'force anyway with "-o -"'])
        try:
            sys.stdout.buffer.write(data)
            sys.stdout.buffer.flush()
        except BrokenPipeError:
            raise SystemExit(0)
        return
    if path == "-":
        try:
            sys.stdout.buffer.write(data)
            sys.stdout.buffer.flush()
        except BrokenPipeError:
            raise SystemExit(0)
        return
    try:
        with open(path, "wb") as f:
            f.write(data)
    except OSError as e:
        # The reference often reports this while writing the header.
        fatal(f'failed to write header: open {path}: {e.strerror.lower() if e.strerror else str(e)}')


# ---------------------------------------------------------------------------
# Main command


def main(argv):
    opts = parse_args(argv)
    decrypt_mode = validate_options(opts, argv)

    input_path = opts.inputs[0] if opts.inputs else None
    stdin_is_input = input_path is None or input_path == "-"

    if decrypt_mode:
        # Load ciphertext first; this matches observed ordering for missing input.
        data = open_input(input_path)
        identities = []
        for p in opts.identities:
            try:
                identities.extend(load_identities(p, stdin_conflict=stdin_is_input))
            except AgeError as e:
                fatal(e.msg, e.hints)
        if opts.plugins:
            # We do not implement the plugin protocol. If a plugin is specified,
            # the reference only starts it when needed; for normal native files it
            # behaves like an identity that won't match.
            pass
        try:
            plaintext = decrypt_age_data(data, identities)
        except AgeError as e:
            fatal(e.msg, e.hints)
        write_output(opts.output, plaintext, encrypting=False)
        return

    # Encryption mode. Open input before parsing recipients; the reference reports
    # input-file errors before malformed recipient strings.
    plaintext = open_input(input_path)

    if opts.passphrase:
        try:
            pw = read_new_passphrase()
        except AgeError as e:
            fatal(e.msg, e.hints)
        out = build_age_file(plaintext, passphrase=pw)
        if opts.armor:
            out = armor_encode(out)
        write_output(opts.output, out, encrypting=True, armor=opts.armor)
        return

    recipient_pubs = []
    try:
        for r in opts.recipients:
            recipient_pubs.append(parse_classic_recipient(r))
        for rf in opts.recipient_files:
            recipient_pubs.extend(load_recipient_file(rf, stdin_conflict=stdin_is_input))
        for ident_path in opts.identities:
            ids = load_identities(ident_path, stdin_conflict=stdin_is_input)
            recipient_pubs.extend(i.public for i in ids)
    except AgeError as e:
        fatal(e.msg, e.hints)

    if opts.plugins:
        # Match the common no-plugin error for data-less plugin encryption.
        pl = opts.plugins[0]
        fatal(f'failed to wrap key for recipient #0: {pl} plugin: couldn\'t start plugin: "{pl}" plugin not found: exec: "age-plugin-{pl}": executable file not found in $PATH',
              [f'you might want to install the "{pl}" plugin', 'visit https://age-encryption.org/awesome#plugins for a list of available plugins'])

    out = build_age_file(plaintext, recipient_pubs=recipient_pubs)
    if opts.armor:
        out = armor_encode(out)
    write_output(opts.output, out, encrypting=True, armor=opts.armor)


if __name__ == "__main__":
    try:
        main(sys.argv[1:])
    except BrokenPipeError:
        try:
            sys.stdout.close()
        except Exception:
            pass
        raise SystemExit(0)
